import React from 'react';
import { DragAndDropAreaProps } from '../../FileMultiUploader.types';
import { UploadFilesImage } from '../upload-files-image';
import {
  Container,
  DragAndDropMessage,
  DragAndDropTitle,
  IconContainer,
  InputLabel,
  StyledInput,
  TextContainer,
} from './DragAndDropArea.styles';

export const DragAndDropArea = ({
  onDrop,
  disabled,
  title = 'Drag your file here or ',
  message = 'We support only DOC, DOCX, XLS, XLSX, CSV or PDF files. Maximum size of 20MB.',
  inputLabel = 'Browse',
  multiple,
  accept,
  ref: forwardedRef,
  size,
  id,
}: DragAndDropAreaProps) => {
  const handleDrop = (event: React.DragEvent) => {
    event.preventDefault();
    const { files } = event.dataTransfer;
    if (files) {
      if (multiple) {
        onDrop(Array.from(files));
      } else {
        onDrop([files[0]]);
      }
    }
  };

  const handleFileInputChange = (event: React.ChangeEvent<HTMLInputElement>) => {
    const { files } = event.target;
    if (files) {
      onDrop(Array.from(files));
    }
  };

  return (
    <Container
      data-testid="drag-and-drop-area"
      ref={forwardedRef}
      onDrop={handleDrop}
      onDragOver={(e) => e.preventDefault()}
      onDragLeave={(e) => e.preventDefault()}
      disabled={disabled}
      size={size}
    >
      <IconContainer disabled={disabled}>
        <UploadFilesImage />
      </IconContainer>
      <TextContainer>
        <DragAndDropTitle disabled={disabled}>
          {title}
          <StyledInput
            data-testid="file-uploader-input"
            id={`file-uploader-input-${id}`}
            type="file"
            accept={accept}
            onChange={handleFileInputChange}
            multiple={multiple}
            disabled={disabled}
          />
          <InputLabel htmlFor={`file-uploader-input-${id}`} disabled={disabled}>
            {inputLabel}
          </InputLabel>
        </DragAndDropTitle>
        <DragAndDropMessage disabled={disabled}>{message}</DragAndDropMessage>
      </TextContainer>
    </Container>
  );
};
